#include <stdio.h>

enum Status {
    STATUS_PENDING,     /* 0. */
    STATUS_READY,       /* 1. */
    STATUS_FAILED,      /* 2. */
};

const char *status_name(enum Status s) {
    switch (s) {                 /* no default: -Wswitch flags missing cases. */
    case STATUS_PENDING: return "pending";
    case STATUS_READY:   return "ready";
    case STATUS_FAILED:  return "failed";
    }
    return "invalid";            /* policy for values outside the enum. */
}

int main(void) {
    printf("%s\n", status_name(STATUS_READY));        /* ready. */
    printf("%s\n", status_name((enum Status)7));      /* invalid. */
    return 0;
}
```

